(() => {
  'use strict';
  const canvas = document.getElementById('world');
  const ctx = canvas.getContext('2d');
  const mapCanvas = document.getElementById('minimap');
  const mapCtx = mapCanvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const rand = (a,b) => a + Math.random()*(b-a);
  const dist = (a,b) => Math.hypot(a.x-b.x,a.y-b.y);
  const WORLD = {w:2800,h:2050};
  const weaponList = [
    {name:'Ashen Longsword',type:'Longsword',damage:26,speed:.48,stamina:18,reach:54,icon:'⚔',desc:'A weathered blade balanced for a steady hand.'},
    {name:'Gravewarden Greatsword',type:'Greatsword',damage:47,speed:.82,stamina:34,reach:70,icon:'╱',desc:'Heavy, slow, and made to end an argument.'},
    {name:'Pilgrim’s Thorn',type:'Dagger',damage:17,speed:.28,stamina:11,reach:42,icon:'†',desc:'A quick weapon for those who keep close.'},
    {name:'Blackroot Spear',type:'Spear',damage:23,speed:.55,stamina:20,reach:78,icon:'↟',desc:'Keep your distance. The forest will not.'},
    {name:'Widowmaker',type:'Curved Sword',damage:31,speed:.42,stamina:19,reach:57,icon:'⌁',desc:'A crescent edge that remembers every wound.'},
    {name:'Cinderbrand',type:'Legendary Blade',damage:59,speed:.60,stamina:27,reach:73,icon:'✦',desc:'A king’s last ember, still burning.'}
  ];
  const bossData = [
    {name:'THE FALLEN KING',title:'THE CROWNLESS',x:1310,y:500,hp:470,damage:24,scale:1.55,reward:180,weapon:5,desc:'The first sovereign, still chained to his throne.'},
    {name:'THE BLOOD MOON KNIGHT',title:'THE RED OATH',x:1940,y:455,hp:560,damage:28,scale:1.18,reward:240,desc:'A knight who serves the moon that no longer rises.'},
    {name:'THE ABYSSAL DRAGON',title:'EATER OF THE DEEP',x:2310,y:1010,hp:840,damage:37,scale:2.1,reward:380,desc:'An ancient hunger beneath the drowned bridge.'},
    {name:'THE HOLLOW SAINT',title:'THE SILENT VIGIL',x:1690,y:1340,hp:630,damage:31,scale:1.5,reward:300,desc:'A cathedral guardian hollowed by centuries of prayer.'},
    {name:'THE WEEPING EXECUTIONER',title:'THE LAST SENTENCE',x:890,y:1480,hp:710,damage:34,scale:1.5,reward:340,desc:'The village headsman, waiting in the gallows mist.'},
    {name:'THE PALE MATRIARCH',title:'MOTHER OF THORNS',x:380,y:1120,hp:650,damage:32,scale:1.35,reward:320,desc:'Rooted in the oldest wood, she calls the lost by name.'},
    {name:'THE IRON PILGRIM',title:'THE UNBROKEN',x:370,y:530,hp:780,damage:36,scale:1.7,reward:390,desc:'A colossus that never reached the holy city.'},
    {name:'THE WRAITH OF CROWNS',title:'THE KINGMAKER',x:1100,y:1010,hp:740,damage:38,scale:1.4,reward:420,desc:'A many-faced specter from the old underground kingdom.'},
    {name:'THE ASHEN SERAPH',title:'WINGS OF RUIN',x:2130,y:1510,hp:930,damage:40,scale:1.75,reward:520,desc:'An angel abandoned by the gods above the catacombs.'},
    {name:'THE LAST GOD',title:'THE END OF ALL THINGS',x:1410,y:1750,hp:1300,damage:48,scale:2.2,reward:1200,desc:'The last divinity, waiting where the world ends.'}
  ];
  const types = [
    {name:'Hollow Soldier',hp:95,damage:12,speed:53,color:'#8b8b78',size:15,reward:28,kind:'soldier'},
    {name:'Ashen Hound',hp:68,damage:15,speed:83,color:'#876b59',size:12,reward:24,kind:'hound'},
    {name:'Grave Knight',hp:160,damage:20,speed:41,color:'#58605c',size:18,reward:48,kind:'knight'},
    {name:'Rootbound Giant',hp:280,damage:28,speed:27,color:'#606a52',size:25,reward:80,kind:'giant'}
  ];
  const state = {started:false,paused:false,player:{x:800,y:800,hp:140,maxHp:140,stamina:100,maxStamina:100,focus:60,maxFocus:60,souls:0,level:1,xp:0,nextXp:100,strength:10,weapon:0,armor:0,attack:0,dodge:0,invuln:0,block:false,face:0,lock:true,rollX:0,rollY:0,lastHit:0},lostSouls:0,checkpoint:{x:800,y:800},unlocked:0,kills:0,boss:null,bossIndex:-1,defeated:Array(10).fill(false),enemies:[],particles:[],trees:[],ruins:[],rocks:[],embers:[],keys:{},stick:{x:0,y:0},mobile:false,settings:{effects:true,low:false},toastTimer:0,combatFlash:0};
  const player=state.player;
  let W=innerWidth,H=innerHeight,DPR=1,camera={x:0,y:0},last=performance.now(),lastAttack=-10,heavyCooldown=-10,toastClock=0,attackHeld=false,now=0;
  const shrine={x:800,y:800,r:48};
  const landmarks=[
    {x:1300,y:500,name:'Fallen Keep',type:'castle'}, {x:1920,y:430,name:'Blood Moon Outpost',type:'village'},
    {x:2320,y:990,name:'The Drowned Bridge',type:'bridge'}, {x:1690,y:1330,name:'Forgotten Cathedral',type:'cathedral'},
    {x:900,y:1460,name:'Haunted Village',type:'village'}, {x:380,y:1120,name:'Blackroot Wood',type:'forest'},
    {x:380,y:530,name:'King’s Causeway',type:'bridge'}, {x:1100,y:1010,name:'Underkingdom Descent',type:'cave'},
    {x:2130,y:1510,name:'Ashen Catacombs',type:'cathedral'}, {x:1410,y:1750,name:'The World’s End',type:'arena'}
  ];
  function initWorld(){
    let seed=87341; const sr=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
    for(let i=0;i<240;i++){const x=sr()*WORLD.w,y=sr()*WORLD.h; if(Math.hypot(x-shrine.x,y-shrine.y)<100)continue;state.trees.push({x,y,r:9+sr()*17,t:sr(),shade:sr()});}
    for(let i=0;i<90;i++)state.rocks.push({x:sr()*WORLD.w,y:sr()*WORLD.h,r:4+sr()*13});
    landmarks.forEach((l,i)=>state.ruins.push({...l,index:i}));
    for(let i=0;i<22;i++)state.embers.push({x:sr()*WORLD.w,y:sr()*WORLD.h,r:1+sr()*2,phase:sr()*6.2,speed:.4+sr()*.7});
    spawnEnemies();
  }
  function spawnEnemies(){
    state.enemies=[];
    const positions=[[940,740,0],[1040,650,0],[1090,830,1],[1170,670,1],[600,710,0],[620,900,2],[1450,760,2],[1770,600,0],[1950,800,1],[1600,1120,0],[1050,1320,2],[740,1200,1],[450,850,3],[2050,1260,0],[1240,1480,2],[2240,700,1],[1370,1020,0],[570,1420,0],[1860,1640,2],[970,400,1]];
    positions.forEach(([x,y,type],i)=>{const t=types[type];state.enemies.push({x,y,homeX:x,homeY:y,hp:t.hp,maxHp:t.hp,damage:t.damage,speed:t.speed,color:t.color,size:t.size,reward:t.reward,name:t.name,kind:t.kind,phase:Math.random()*6,attack:0,stun:0,dead:false,patrol:50+i%5*10});});
  }
  function resize(){W=innerWidth;H=innerHeight;DPR=Math.min(devicePixelRatio||1,state.settings.low?1:1.5);canvas.width=Math.floor(W*DPR);canvas.height=Math.floor(H*DPR);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0);state.mobile=W<740;document.getElementById('mobile-controls').classList.toggle('show',state.started&&state.mobile);}
  addEventListener('resize',resize);resize();initWorld();
  function showToast(message,duration=2500){const t=$('toast');t.textContent=message;t.classList.add('show');state.toastTimer=duration;}
  function weapon(){return weaponList[player.weapon]||weaponList[0];}
  function levelUp(){while(player.xp>=player.nextXp){player.xp-=player.nextXp;player.level++;player.nextXp=Math.floor(player.nextXp*1.48);player.maxHp+=12;player.maxStamina+=5;player.maxFocus+=3;player.hp=player.maxHp;player.stamina=player.maxStamina;showToast(`LEVEL ${player.level} · THE EMBERS GROW STRONGER`);}}
  function takeHit(amount,source){if(player.invuln>0||player.dodge>0)return;if(player.block){const fee=amount*.65;player.stamina=Math.max(0,player.stamina-fee);amount*=player.stamina>0?.2:.8;if(player.stamina<=0)showToast('GUARD BROKEN');else amount=Math.max(1,amount);}player.hp=Math.max(0,player.hp-amount);player.lastHit=now;state.combatFlash=.18;burst(player.x,player.y,'#b95748',9);if(player.hp<=0)die();}
  function die(){if($('death-modal').classList.contains('open'))return;state.lostSouls=player.souls;player.souls=0;state.boss=null;state.bossIndex=-1;player.hp=player.maxHp;player.stamina=player.maxStamina;player.focus=player.maxFocus;player.x=state.checkpoint.x;player.y=state.checkpoint.y;player.invuln=1.5;$('death-copy').textContent=state.lostSouls?`${state.lostSouls} runes lie where you fell. Recover them before they fade.`:'The embers carry you back to the shrine.';$('death-modal').classList.add('open');}
  function rise(){if(state.lostSouls){/* retained at last death position in a world pickup */state.soulsDrop={x:state.lastDeathX||player.x,y:state.lastDeathY||player.y,value:state.lostSouls};} $('death-modal').classList.remove('open');player.x=state.checkpoint.x;player.y=state.checkpoint.y;}
  function burst(x,y,color,n=8){for(let i=0;i<n;i++)state.particles.push({x,y,vx:rand(-80,80),vy:rand(-80,80),life:rand(.25,.7),max:.7,color,size:rand(1.5,4)});}
  function nearestBoss(){let best=null,bd=Infinity;bossData.forEach((b,i)=>{if(state.defeated[i])return;const d=Math.hypot(player.x-b.x,player.y-b.y);if(d<bd){bd=d;best={...b,index:i,d};}});return best;}
  function activateBoss(b){if(!b||b.index>state.unlocked)return;if(!state.boss){state.boss={...b,hp:b.hp,maxHp:b.hp,phase:0,attack:0,stun:0,active:true,attackType:0,intro:2.5,lastAttack:0,step:0};state.bossIndex=b.index;$('boss-hud').style.display='block';$('boss-name').textContent=b.name;$('boss-phase').textContent=b.title;showToast(`A FOE APPROACHES · ${b.name}`,3500);}}
  function attack(heavy=false){if(!state.started||state.paused||player.hp<=0||player.dodge>0)return;const w=weapon(),cost=w.stamina*(heavy?1.65:1);if(player.stamina<cost){showToast('NOT ENOUGH STAMINA',1000);return;}const cooldown=heavy?w.speed*1.55:w.speed;if(now-(heavy?heavyCooldown:lastAttack)<cooldown)return;if(heavy)heavyCooldown=now;else lastAttack=now;player.stamina-=cost;player.attack=heavy?.43:.27;const targets=[];if(state.boss&&state.boss.active)targets.push(state.boss);state.enemies.forEach(e=>{if(!e.dead)targets.push(e);});let hit=false;
    let target=null,score=Infinity;for(const e of targets){const d=Math.hypot(e.x-player.x,e.y-player.y);let angle=Math.atan2(e.y-player.y,e.x-player.x);let diff=Math.abs(Math.atan2(Math.sin(angle-player.face),Math.cos(angle-player.face)));if(d<w.reach+(e.size||0)&&diff<(heavy?1.25:1.0)&&d<score){target=e;score=d;}}
    if(target){const dmg=Math.round(w.damage*(1+player.strength*.035)*(heavy?1.55:1)*(player.armor?1.08:1));target.hp-=dmg;target.stun=.25;burst(target.x,target.y,target===state.boss?'#cf6551':'#c3a979',10);hit=true;if(target===state.boss){if(target.hp<=target.maxHp*.5&&target.phase===0){target.phase=1;target.damage*=1.35;target.speed*=1.18;showToast('THE FOE CHANGES · PHASE II');$('boss-phase').textContent='PHASE II · WRATH AWAKENED';}if(target.hp<=0)winBoss(target);}else if(target.hp<=0){target.dead=true;state.kills++;player.souls+=target.reward;player.xp+=Math.round(target.reward*.65);levelUp();showToast(`${target.name} · +${target.reward} RUNES`,1600);} }
    if(!hit){for(let i=0;i<5;i++){const a=player.face+rand(-.55,.55),d=rand(22,w.reach);state.particles.push({x:player.x+Math.cos(a)*d,y:player.y+Math.sin(a)*d,vx:Math.cos(a)*rand(10,45),vy:Math.sin(a)*rand(10,45),life:.2,max:.2,color:'#c4ae80',size:2});}}
  }
  function winBoss(b){state.boss=null;state.defeated[b.index]=true;state.unlocked=Math.max(state.unlocked,b.index+1);player.souls+=b.reward;player.xp+=b.reward;levelUp();if(b.weapon!==undefined){player.weapon=b.weapon;showToast(`VICTORY · ${b.reward} RUNES · CINDERBRAND CLAIMED`,2500);}else showToast(`VICTORY · ${b.reward} RUNES`,2000);$('boss-hud').style.display='none';$('victory-title').textContent=b.name==='THE LAST GOD'?'THE WORLD REMEMBERS':'THE FOE IS SILENT';$('victory-copy').textContent=`${b.desc} The ember is yours. ${b.index<9?'A new path stirs beyond the mist.':'The forgotten age is ended.'}`;$('victory-modal').classList.add('open');}
  function dodge(){if(!state.started||state.paused||player.dodge>0||player.stamina<25)return;player.stamina-=25;player.dodge=.42;player.invuln=.48;const {x,y}=moveVector();let l=Math.hypot(x,y);if(l<.05){player.rollX=Math.cos(player.face);player.rollY=Math.sin(player.face);}else{player.rollX=x/l;player.rollY=y/l;}player.attack=0;}
  function moveVector(){const k=state.keys;let x=(k.d||k.arrowright?1:0)-(k.a||k.arrowleft?1:0)+state.stick.x;let y=(k.s||k.arrowdown?1:0)-(k.w||k.arrowup?1:0)+state.stick.y;let len=Math.hypot(x,y);if(len>1){x/=len;y/=len;}return{x,y};}
  function rest(){if(Math.hypot(player.x-shrine.x,player.y-shrine.y)>68)return;state.checkpoint={x:shrine.x+40,y:shrine.y+5};player.hp=player.maxHp;player.stamina=player.maxStamina;player.focus=player.maxFocus;state.lostSouls=0;state.soulsDrop=null;spawnEnemies();if(state.boss){state.boss=null;$('boss-hud').style.display='none';}showToast('THE ASHES REMEMBER · RESTED AT SHRINE');}
  function interact(){if(Math.hypot(player.x-shrine.x,player.y-shrine.y)<74){rest();return;}if(state.soulsDrop&&Math.hypot(player.x-state.soulsDrop.x,player.y-state.soulsDrop.y)<48){player.souls+=state.soulsDrop.value;showToast(`${state.soulsDrop.value} RUNES RECOVERED`);state.soulsDrop=null;state.lostSouls=0;return;}const b=nearestBoss();if(b&&b.d<170&&b.index<=state.unlocked){activateBoss(b);return;}showToast('THE MIST HAS NO ANSWER');}

  function update(dt){now+=dt;if(!state.started||state.paused)return;dt=Math.min(dt,.04);player.invuln=Math.max(0,player.invuln-dt);player.attack=Math.max(0,player.attack-dt);player.dodge=Math.max(0,player.dodge-dt);player.stamina=Math.min(player.maxStamina,player.stamina+dt*(player.block?5:21));player.focus=Math.min(player.maxFocus,player.focus+dt*2);if(player.block&&player.stamina<=0)player.block=false;
    const v=moveVector();if(player.dodge>0){player.x+=player.rollX*380*dt;player.y+=player.rollY*380*dt;}else{const speed=player.block?105:player.attack?110:player.armor?148:166;player.x+=v.x*speed*dt;player.y+=v.y*speed*dt;if(v.x||v.y){if(!player.block)player.face=Math.atan2(v.y,v.x);}}
    player.x=clamp(player.x,30,WORLD.w-30);player.y=clamp(player.y,30,WORLD.h-30);
    // Soft collision with trees and ruin walls; momentum remains responsive.
    for(const t of state.trees){const dx=player.x-t.x,dy=player.y-t.y,d=Math.hypot(dx,dy),min=t.r*.6+9;if(d<min&&d>0){player.x+=dx/d*(min-d);player.y+=dy/d*(min-d);}}
    const targetBoss=nearestBoss();if(!state.boss&&targetBoss&&targetBoss.index<=state.unlocked&&targetBoss.d<260)activateBoss(targetBoss);
    state.enemies.forEach(e=>{if(e.dead)return;e.phase+=dt;const d=Math.hypot(player.x-e.x,player.y-e.y),aggro=d<220;let vx=0,vy=0;if(e.stun>0)e.stun-=dt;else if(aggro){if(d>e.size+19){vx=(player.x-e.x)/Math.max(d,1);vy=(player.y-e.y)/Math.max(d,1);e.x+=vx*e.speed*dt;e.y+=vy*e.speed*dt;}else if(e.attack<=0){e.attack=.9+Math.random()*.35;setTimeout(()=>{if(!e.dead&&Math.hypot(player.x-e.x,player.y-e.y)<e.size+34)takeHit(e.damage,e);},400);}}else{e.x=e.homeX+Math.cos(e.phase*.28)*e.patrol;e.y=e.homeY+Math.sin(e.phase*.34)*e.patrol*.6;}e.attack=Math.max(0,e.attack-dt);});
    if(state.boss){const b=state.boss;b.intro=Math.max(0,b.intro-dt);const d=Math.hypot(player.x-b.x,player.y-b.y);if(b.stun>0)b.stun-=dt;else if(d>105){b.x+=(player.x-b.x)/Math.max(d,1)*b.speed*dt;b.y+=(player.y-b.y)/Math.max(d,1)*b.speed*dt;}else if(b.attack<=0&&b.intro<=0){b.attack=b.phase?1.05:1.5;b.step++;const heavy=b.phase===1&&b.step%3===0;const wind=heavy?520:360;setTimeout(()=>{if(!state.boss||state.boss!==b)return;const range=(b.scale*22)+(heavy?25:5);if(Math.hypot(player.x-b.x,player.y-b.y)<range)takeHit(b.damage*(heavy?1.45:1),b);else if(heavy){const dx=player.x-b.x,dy=player.y-b.y,l=Math.hypot(dx,dy)||1;b.x+=dx/l*34;b.y+=dy/l*34;}},wind);}
      b.attack=Math.max(0,b.attack-dt);$('boss-fill').style.width=`${clamp(b.hp/b.maxHp*100,0,100)}%`;$('boss-health-label').textContent=`${Math.max(0,Math.ceil(b.hp/b.maxHp*100))}%`;}
    if(state.soulsDrop&&Math.hypot(player.x-state.soulsDrop.x,player.y-state.soulsDrop.y)<36){player.souls+=state.soulsDrop.value;showToast(`${state.soulsDrop.value} RUNES RECOVERED`);state.soulsDrop=null;state.lostSouls=0;}
    state.particles=state.particles.filter(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.97;p.vy*=.97;return p.life>0;});state.combatFlash=Math.max(0,state.combatFlash-dt);if(state.toastTimer>0){state.toastTimer-=dt;if(state.toastTimer<=0)$('toast').classList.remove('show');}
    $('health-fill').style.width=`${player.hp/player.maxHp*100}%`;$('health-text').textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;$('stamina-fill').style.width=`${player.stamina/player.maxStamina*100}%`;$('focus-fill').style.width=`${player.focus/player.maxFocus*100}%`;$('level').textContent=String(player.level).padStart(2,'0');$('souls').textContent=player.souls.toLocaleString();
    const b=nearestBoss();$('objective-text').textContent=state.boss?`Defeat ${state.boss.name.toLowerCase()}`:state.unlocked>=10?'The world remembers':`Seek ${bossData[state.unlocked].name.toLowerCase()}`;$('objective-distance').textContent=b?`${Math.round(b.d/10)}M · ${b.d<220?'NEARBY':'NORTH'}`:'PATH CLEARED';$('interact-prompt').classList.toggle('visible',Math.hypot(player.x-shrine.x,player.y-shrine.y)<70);
    camera.x=clamp(player.x-W/2,0,Math.max(0,WORLD.w-W));camera.y=clamp(player.y-H/2,0,Math.max(0,WORLD.h-H));
  }

  function worldToScreen(x,y){return{x:x-camera.x,y:y-camera.y};}
  function drawGround(){
    ctx.fillStyle='#252d28';ctx.fillRect(0,0,W,H);
    const ox=-camera.x,oy=-camera.y;
    // broad worn roads and branching kingdom paths
    ctx.save();ctx.translate(ox,oy);ctx.lineCap='round';ctx.lineJoin='round';
    ctx.strokeStyle='#373a32';ctx.lineWidth=118;ctx.beginPath();ctx.moveTo(795,825);ctx.bezierCurveTo(880,700,1000,725,1160,630);ctx.bezierCurveTo(1260,570,1270,510,1310,500);ctx.stroke();
    ctx.strokeStyle='#353a32';ctx.lineWidth=78;ctx.beginPath();ctx.moveTo(795,825);ctx.bezierCurveTo(730,980,590,1080,380,1120);ctx.moveTo(810,820);ctx.bezierCurveTo(900,1030,900,1250,900,1460);ctx.moveTo(825,790);ctx.bezierCurveTo(1050,810,1300,830,1500,1000);ctx.bezierCurveTo(1620,1120,1650,1260,1690,1330);ctx.moveTo(820,790);ctx.bezierCurveTo(730,630,550,550,380,530);ctx.stroke();
    ctx.strokeStyle='#443d32';ctx.lineWidth=8;ctx.setLineDash([2,19]);ctx.beginPath();ctx.moveTo(795,825);ctx.bezierCurveTo(880,700,1000,725,1160,630);ctx.bezierCurveTo(1260,570,1270,510,1310,500);ctx.moveTo(795,825);ctx.bezierCurveTo(730,980,590,1080,380,1120);ctx.stroke();ctx.setLineDash([]);
    // ground patches
    for(let i=0;i<landmarks.length;i++){const l=landmarks[i];const g=ctx.createRadialGradient(l.x,l.y,50,l.x,l.y,i===5?330:230);g.addColorStop(0,i===5?'#28352a':'#30322c');g.addColorStop(1,'#252d28');ctx.fillStyle=g;ctx.beginPath();ctx.arc(l.x,l.y,i===5?330:230,0,Math.PI*2);ctx.fill();}
    // shattered paving around the shrine
    for(let i=0;i<28;i++){const a=i*2.399,r=65+(i%5)*15,x=shrine.x+Math.cos(a)*r,y=shrine.y+Math.sin(a)*r;ctx.fillStyle=i%2?'#555349':'#47483f';ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+rand(8,20),y-rand(2,7));ctx.lineTo(x+rand(15,26),y+rand(5,15));ctx.lineTo(x-rand(4,10),y+rand(7,15));ctx.closePath();ctx.fill();}
    ctx.restore();
  }
  function drawLandmark(l){const p=worldToScreen(l.x,l.y);if(p.x<-250||p.x>W+250||p.y<-250||p.y>H+250)return;ctx.save();ctx.translate(p.x,p.y);
    if(l.type==='castle'||l.type==='cathedral'){
      const s=l.type==='castle'?1:1.2;ctx.fillStyle='#121817';ctx.shadowColor='#080a09';ctx.shadowBlur=18;
